  gC.line(apx.x, apx.y, cx0 + L + 20, apx.y).stroke({ color: COL.ink, width: 1.2 });
  gC.path(vBracePath(cx0 + L + 22, apx.y, by, 7)).fill('none').stroke({ color: COL.ink, width: 1.5 });
  txt(gC, 'sin x', cx0 + L + 44, (apx.y + by) / 2 + 6, { anchor: 'start', size: 18, italic: true, halo: 3 });
  angleMark(gC, cx0, by, 30, x, 44, 16);
  txt(gC, '1', cx0 + L / 2, by + 27, { size: 19, halo: 3 });
  interactive(polyC, 'Inner triangle: area sin x / 2 = ' + (s / 2).toFixed(3), 'sin', POP.sin[0], POP.sin[1]);
}

/* ---------- right band : overlaid (nesting) view ---------- */
function drawOverlay(x) {
  var O = { x: 540, y: 352 }, R = 200, topLim = 126;
  var s = Math.sin(x), c = Math.cos(x), t = Math.tan(x);
  var apexY = O.y - R * t, cl = apexY < topLim;
  var tt = (O.y - topLim) / (O.y - apexY);

  draw.path(arcPath(O.x, O.y, R, 0, Math.PI / 2)).fill('none')
    .stroke({ color: COL.blue, width: 2, opacity: 0.35 }).attr('stroke-dasharray', '4,5');

  var gA = draw.group(); push('tan', gA);
  var pts = cl
    ? [[O.x, O.y], [O.x + R, O.y], [O.x + R, topLim], [O.x + tt * R, topLim]]
    : [[O.x, O.y], [O.x + R, O.y], [O.x + R, apexY]];
  var pA = gA.polygon(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
    .fill({ color: COL.fill, opacity: 1 }).stroke({ color: COL.red, width: 2.5, linejoin: 'round' });
  interactive(pA, 'Outer triangle: tan x / 2 = ' + (t / 2).toFixed(3), 'tan', POP.tan[0], POP.tan[1]);
  txt(gA, cl ? 'tan x = ' + t.toFixed(2) + ' ↑' : 'tan x', O.x + R + 12,
    cl ? topLim + 16 : (O.y + apexY) / 2 + 5, { anchor: 'start', size: 17, italic: true, halo: 3 });

  var gB = draw.group(); push('sector', gB);
  var ae = { x: O.x + R * c, y: O.y - R * s };
  var d = 'M' + O.x + ',' + O.y + ' L' + (O.x + R) + ',' + O.y +
    ' A' + R + ',' + R + ' 0 0 0 ' + ae.x + ',' + ae.y + ' Z';
  var pB = gB.path(d).fill({ color: COL.sectorFill, opacity: 0.92 })
    .stroke({ color: COL.blue, width: 3 });
  interactive(pB, 'Sector: x / 2 = ' + (x / 2).toFixed(3), 'sector', POP.sector[0], POP.sector[1]);

  var gC = draw.group(); push('sin', gC);
  var pC = gC.polygon([[O.x, O.y], [O.x + R, O.y], [ae.x, ae.y]]
    .map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
    .fill({ color: COL.innerFill, opacity: 0.9 }).stroke({ color: COL.dark, width: 2.2, linejoin: 'round' });
  gC.line(ae.x, O.y, ae.x, ae.y).stroke({ color: COL.dark, width: 1.4 }).attr('stroke-dasharray', '5,4');
  txt(gC, 'sin x', ae.x - 6, (ae.y + O.y) / 2 + 5, { anchor: 'end', size: 16, italic: true, halo: 3 });
  interactive(pC, 'Inner triangle: sin x / 2 = ' + (s / 2).toFixed(3), 'sin', POP.sin[0], POP.sin[1]);

  draw.line(O.x, O.y, O.x + R, O.y).stroke({ color: COL.dark, width: 4 });
  txt(draw, '1', O.x + R / 2, O.y + 26, { size: 19, halo: 3 });
  angleMark(draw, O.x, O.y, 40, x, 56, 18);

  /* legend */
  var items = [
    { k: 'tan', c: COL.fill, sc: COL.red, l: 'outer triangle', v: 'tan x / 2 = ' + (t / 2).toFixed(3) },
    { k: 'sector', c: COL.sectorFill, sc: COL.blue, l: 'sector', v: 'x / 2 = ' + (x / 2).toFixed(3) },
    { k: 'sin', c: COL.innerFill, sc: COL.dark, l: 'inner triangle', v: 'sin x / 2 = ' + (s / 2).toFixed(3) }
  ];
  var lx = 840, ly = 155;
  items.forEach(function (it, i) {
    var gl = draw.group(); push(it.k, gl, 0.3);
    var y = ly + i * 40;
    gl.rect(26, 17).move(lx, y - 13).fill(it.c).stroke({ color: it.sc, width: 2 });
    txt(gl, it.l + ':', lx + 34, y, { anchor: 'start', size: 15 });
    txt(gl, it.v, lx + 160, y, { anchor: 'start', size: 15, italic: true });
    var hit = gl.rect(320, 34).move(lx - 4, y - 18).fill('#fff').opacity(0);
    interactive(hit, POP[it.k][0], it.k, POP[it.k][0], POP[it.k][1]);
  });
  txt(draw, 'inner triangle  ⊂  sector  ⊂  outer triangle', lx, ly + 132,
    { anchor: 'start', size: 15, color: '#444' });
  txt(draw, 'cos x  ≤  sin x / x  ≤  1 / cos x', lx, ly + 166,
    { anchor: 'start', size: 17, italic: true });
  txt(draw, c.toFixed(3) + '   ≤   ' + (s / x).toFixed(3) + '   ≤   ' + (1 / c).toFixed(3),
    lx + 6, ly + 194, { anchor: 'start', size: 17, color: COL.dark });
}

/* ---------- caption + formula rows ---------- */
function drawCaptions(x) {
  var s = Math.sin(x), c = Math.cos(x), t = Math.tan(x);
  var capY = 402, barY = 452, cs = [545, 805, 1045];
  var defs = [
    { k: 'tan', cap: 'Area of triangle', n: 'tan x', d: '2' },
    { k: 'sector', cap: 'Area of sector', n: 'x', d: '2' },
    { k: 'sin', cap: 'Area of triangle', n: 'sin x', d: '2' }
  ];
  defs.forEach(function (o, i) {
    var g = draw.group(); push(o.k, g, 0.28);
    var hot = state.hl === o.k;
    var size = hot ? 25 : 20, col = hot ? COL.dark : COL.ink;
    var tc = txt(g, o.cap, cs[i], capY, { size: hot ? 22 : 21, color: col });
    interactive(tc, POP[o.k][0], o.k, POP[o.k][0], POP[o.k][1]);
    var w = Math.max(o.n.length, o.d.length) * size * 0.44 + 8;
    txt(g, o.n, cs[i], barY - 7, { size: size, italic: true, color: col });
    g.line(cs[i] - w / 2, barY, cs[i] + w / 2, barY).stroke({ color: col, width: 1.7 });
    txt(g, o.d, cs[i], barY + size + 3, { size: size, color: col });
    var hit = g.rect(w + 26, 60).move(cs[i] - w / 2 - 13, barY - size - 12).fill('#fff').opacity(0);
    interactive(hit, POP[o.k][0], o.k, POP[o.k][0], POP[o.k][1]);
  });
  [675, 925].forEach(function (px) {
    txt(draw, '≥', px, capY, { size: 22 });
    txt(draw, '≥', px, barY + 7, { size: 22 });
  });
}

/* ---------- numeric readout ---------- */
function drawReadout(x) {
  var s = Math.sin(x), c = Math.cos(x), t = Math.tan(x);
  var rx = 56;
  txt(draw, 'x = ' + x.toFixed(2) + ' rad      sin x = ' + s.toFixed(3) + '      tan x = ' + t.toFixed(3),
    rx, 452, { anchor: 'start', size: 15 });
  txt(draw, 'sin x/2 = ' + (s / 2).toFixed(3) + '  ≤  x/2 = ' + (x / 2).toFixed(3) +
    '  ≤  tan x/2 = ' + (t / 2).toFixed(3), rx, 476, { anchor: 'start', size: 15, color: COL.dark });
  txt(draw, 'cos x = ' + c.toFixed(3) + '  ≤  sin x / x = ' + (s / x).toFixed(3) +
    '  ≤  1/cos x = ' + (1 / c).toFixed(3), rx, 500, { anchor: 'start', size: 15, color: '#1a5fa8' });

  var ui = document.getElementById('uiReadout');
  if (ui) {
    ui.innerHTML = 'x = ' + x.toFixed(2) + ' rad<br>' +
      'sin x/2 = ' + (s / 2).toFixed(4) + ' &le; x/2 = ' + (x / 2).toFixed(4) +
      ' &le; tan x/2 = ' + (t / 2).toFixed(4) + '<br>' +
      '<b>sin x / x = ' + (s / x).toFixed(4) + '</b>  (between cos x = ' + c.toFixed(4) +
      ' and 1/cos x = ' + (1 / c).toFixed(4) + ')';
  }
}

/* ---------- render ---------- */
function render() {
  draw.clear();
  regionGroups = [];
  var x = state.x;
  drawLeft(x);
  if (state.overlaid) drawOverlay(x); else drawPanels(x);
  drawCaptions(x);
  drawReadout(x);
  applyHighlight();
}

/* ---------- interaction handlers ---------- */
function update_angleX(v) { state.x = Math.max(0.03, +v); render(); }
function toggle_overlayMode(on) { state.overlaid = !!on; render(); }
function setHighlight(k) {
  state.hl = (state.hl === k) ? null : k;
  if (k === null) state.hl = null;
  render();
}

/* ---------- demo steps ---------- */
var steps = [
  {
    title: 'Unit-circle setup', angleX: 0.8, ov: false,
    narration: 'A ray at angle x meets the unit circle at (cos x, sin x) and the vertical tangent line at (1, tan x). Everything in the argument is built from these points and the base of length 1.'
  },
  {
    title: 'Three regions', angleX: 0.8, ov: false,
    narration: 'Big triangle: area tan x / 2. Sector: area x / 2 (radius 1). Small triangle: area sin x / 2. Click a shape or caption to isolate a region and read its formula.'
  },
  {
    title: 'Nesting revealed', angleX: 0.8, ov: true,
    narration: 'Overlaid on one unit circle: the small triangle sits inside the sector, which sits inside the big triangle. Containment of regions is exactly why sin x / 2 ≤ x / 2 ≤ tan x / 2.'
  },
  {
    title: 'Widen the angle', angleX: 1.4, ov: true,
    narration: 'Push x toward π/2 and the outer triangle blows up (tan x runs off the panel) while the inner triangle barely grows — the bound is loose, and sin x / x is far from 1.'
  },
  {
    title: 'Squeeze toward zero', angleX: 0.1, ov: true,
    narration: 'Shrink x toward 0: the three shapes become nearly indistinguishable. Dividing sin x/2 ≤ x/2 ≤ tan x/2 by sin x/2 gives cos x ≤ sin x / x ≤ 1/cos x, and both bounds tend to 1.'
  }
];
var stepIdx = 0;
function setStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  var st = steps[stepIdx];
  var sl = document.getElementById('angleXInput');
  sl.value = st.angleX;
  document.getElementById('angleXVal').value = st.angleX.toFixed(2);
  var cb = document.getElementById('overlayModeInput');
  cb.checked = st.ov;
  state.x = st.angleX; state.overlaid = st.ov; state.hl = null;
  render();
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + '/' + steps.length + ' · ' + st.title;
}
function nextStep() { setStep(stepIdx + 1); }
function prevStep() { setStep(stepIdx - 1); }

setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Because the unit-circle sector of angle x is squeezed between an inner triangle of area sin x / 2 and an outer triangle of area tan x / 2, the inequality sin x ≤ x ≤ tan x forces sin x / x → 1 as x → 0.
KEY INSIGHT (what students should walk away understanding): The sector is geometrically sandwiched between two triangles, so its area x/2 is sandwiched between sin x / 2 and tan x / 2 — and as x → 0 the sandwich closes, forcing sin x / x to 1.
DEMO STEPS: 5 guided steps — implement the step player in #ui

