// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 820, 390);

var COL = {
  blue: '#1f9ad6', red: '#f2635f', fill: '#fce3db', dark: '#8c1d18',
  ink: '#111', sectorFill: '#cfe9f7', innerFill: '#f6b3a9'
};
var FONT = 'Georgia,"Times New Roman",serif';
var state = { x: 0.8, overlaid: false, hl: null };
var regionGroups = [];

/* ---------- small helpers ---------- */
function txt(g, s, x, y, opt) {
  opt = opt || {};
  var t = (typeof g.plain === 'function') ? g.plain(String(s)) : g.text(String(s));
  t.font({
    family: FONT, size: opt.size || 16, anchor: opt.anchor || 'middle',
    style: opt.italic ? 'italic' : 'normal', weight: opt.weight || 'normal'
  });
  t.fill(opt.color || COL.ink);
  t.attr({ x: x, y: y });
  var sp = t.node.getElementsByTagName('tspan');
  for (var i = 0; i < sp.length; i++) { sp[i].setAttribute('x', x); sp[i].setAttribute('dy', 0); }
  if (opt.halo) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': opt.halo, 'stroke-linejoin': 'round' });
  }
  return t;
}
function arrowHead(g, x, y, ang, s, color) {
  var p = [[x, y],
  [x - s * Math.cos(ang - 0.42), y - s * Math.sin(ang - 0.42)],
  [x - s * Math.cos(ang + 0.42), y - s * Math.sin(ang + 0.42)]];
  return g.polygon(p.map(function (q) { return q[0] + ',' + q[1]; }).join(' ')).fill(color);
}
function arcPath(cx, cy, r, a0, a1) {
  var x0 = cx + r * Math.cos(a0), y0 = cy - r * Math.sin(a0);
  var x1 = cx + r * Math.cos(a1), y1 = cy - r * Math.sin(a1);
  var large = (a1 - a0) > Math.PI ? 1 : 0;
  return 'M' + x0 + ',' + y0 + ' A' + r + ',' + r + ' 0 ' + large + ' 0 ' + x1 + ',' + y1;
}
function hBracePath(x1, x2, y, h) {
  var m = (x1 + x2) / 2, a = (m - x1) / 2, b = (x2 - m) / 2;
  return 'M ' + x1 + ' ' + y +
    ' q 0 ' + h + ' ' + a + ' ' + h +
    ' q ' + a + ' 0 ' + a + ' ' + h +
    ' q 0 ' + (-h) + ' ' + b + ' ' + (-h) +
    ' q ' + b + ' 0 ' + b + ' ' + (-h);
}
function vBracePath(x, y1, y2, w) {
  var m = (y1 + y2) / 2, a = (m - y1) / 2, b = (y2 - m) / 2;
  return 'M ' + x + ' ' + y1 +
    ' q ' + w + ' 0 ' + w + ' ' + a +
    ' q 0 ' + a + ' ' + w + ' ' + a +
    ' q ' + (-w) + ' 0 ' + (-w) + ' ' + b +
    ' q 0 ' + b + ' ' + (-w) + ' ' + b;
}
function dot(g, x, y, r) {
  return g.circle((r || 4.8) * 2).center(x, y).fill(COL.red);
}
function angleMark(g, cx, cy, r, x, lblR, size) {
  g.path(arcPath(cx, cy, r, 0, x)).fill('none').stroke({ color: COL.ink, width: 1.5 });
  var tx = cx + r * Math.cos(x), ty = cy - r * Math.sin(x);
  arrowHead(g, tx, ty, Math.atan2(-Math.cos(x), -Math.sin(x)), 8, COL.ink);
  var la = x * 0.52;
  txt(g, 'x', cx + lblR * Math.cos(la), cy - lblR * Math.sin(la) + 5,
    { size: size || 17, italic: true, halo: 3 });
}
function interactive(el, tip, key, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { setHighlight(key); showPopup(title, body); });
}
var POP = {
  tan: ['Outer triangle — area tan x / 2',
    'Its base is the radius of length 1 and its height is the tangent segment of length tan x, so its area is (1 · tan x)/2. This triangle CONTAINS the sector, which is why tan x / 2 ≥ x / 2.'],
  sector: ['Circular sector — area x / 2',
